import random
import math

def is_square(n):
    if n < 0: return False
    r = int(math.isqrt(n))
    return r*r == n

# Generate a random function where f(even)=0, f(odd)=random square
funcs = []
for _ in range(10):
    f = {}
    for x in range(-50, 50):
        if x % 2 == 0:
            f[x] = 0
        else:
            f[x] = random.choice([0, 1, 4, 9, 16, 25, 36, 49, 64, 81])
    funcs.append(f)

def check_func(f):
    domain = list(f.keys())
    for a in domain:
        for b in domain:
            if 2*a in f and (f[a] - b) in f:
                val = f[f[a] - b] + b * f[2*a]
                if not is_square(val):
                    return False
    return True

all_valid = True
for i, f in enumerate(funcs):
    if not check_func(f):
        all_valid = False
        print(f"Function {i} failed!")

print("All random f(even)=0, f(odd)=square functions valid:", all_valid)
